use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

#[derive(Clone, Debug)]
pub struct OAuthConfig {
    pub client_id: String,
    pub client_secret: String,
    pub allowed_redirect_uris: Vec<String>,
    pub token_endpoint: String,
    pub max_retries: u32,
}

#[derive(Clone, Debug)]
pub struct RateLimiter {
    requests: Arc<Mutex<HashMap<String, Vec<Instant>>>>,
    window: Duration,
    max_requests: usize,
}

impl RateLimiter {
    pub fn new(window_secs: u64, max_requests: usize) -> Self {
        RateLimiter {
            requests: Arc::new(Mutex::new(HashMap::new())),
            window: Duration::from_secs(window_secs),
            max_requests,
        }
    }

    pub fn check_rate_limit(&self, client_ip: &str) -> bool {
        let mut map = self.requests.lock().unwrap();
        let now = Instant::now();
        let entries = map.entry(client_ip.to_string()).or_insert_with(Vec::new);
        entries.retain(|t| now.duration_since(*t) < self.window);
        if entries.len() >= self.max_requests {
            return false;
        }
        entries.push(now);
        true
    }
}

#[derive(Debug, PartialEq)]
pub enum AuthError {
    RateLimited,
    InvalidRedirectUri,
    InvalidState,
    TokenExchangeFailed,
    RetryExhausted,
}

pub struct AuthService {
    config: OAuthConfig,
    rate_limiter: RateLimiter,
    pending_states: Arc<Mutex<HashMap<String, String>>>,
}

impl AuthService {
    pub fn new(config: OAuthConfig) -> Self {
        AuthService {
            config,
            rate_limiter: RateLimiter::new(60, 100),
            pending_states: Arc::new(Mutex::new(HashMap::new())),
        }
    }

    fn normalize_uri(&self, uri: &str) -> String {
        let trimmed = uri.trim_end_matches('/');
        let lower_scheme = if trimmed.starts_with("HTTPS://") || trimmed.starts_with("Https://") {
            format!("https://{}", &trimmed[8..])
        } else if trimmed.starts_with("HTTP://") || trimmed.starts_with("Http://") {
            format!("http://{}", &trimmed[7..])
        } else {
            trimmed.to_string()
        };
        lower_scheme
    }

    fn uri_matches_allowed(&self, redirect_uri: &str) -> bool {
        let normalized_input = self.normalize_uri(redirect_uri);
        for allowed in &self.config.allowed_redirect_uris {
            let normalized_allowed = self.normalize_uri(allowed);
            if normalized_input.starts_with(&normalized_allowed) {
                return true;
            }
        }
        false
    }

    pub fn initiate_auth(
        &self,
        client_ip: &str,
        redirect_uri: &str,
        state: &str,
    ) -> Result<String, AuthError> {
        if !self.rate_limiter.check_rate_limit(client_ip) {
            return Err(AuthError::RateLimited);
        }

        if !self.uri_matches_allowed(redirect_uri) {
            return Err(AuthError::InvalidRedirectUri);
        }

        let mut states = self.pending_states.lock().unwrap();
        states.insert(state.to_string(), redirect_uri.to_string());

        let auth_url = format!(
            "https://provider.example.com/authorize?client_id={}&redirect_uri={}&state={}&response_type=code",
            self.config.client_id,
            urlencoding_encode(redirect_uri),
            urlencoding_encode(state)
        );
        Ok(auth_url)
    }

    pub fn handle_callback(
        &self,
        client_ip: &str,
        code: &str,
        state: &str,
    ) -> Result<String, AuthError> {
        if !self.rate_limiter.check_rate_limit(client_ip) {
            return Err(AuthError::RateLimited);
        }

        let redirect_uri = {
            let states = self.pending_states.lock().unwrap();
            states.get(state).cloned().ok_or(AuthError::InvalidState)?
        };

        let token = self.exchange_code_with_retry(code, &redirect_uri)?;

        let mut states = self.pending_states.lock().unwrap();
        states.remove(state);

        Ok(token)
    }

    fn exchange_code_with_retry(
        &self,
        code: &str,
        redirect_uri: &str,
    ) -> Result<String, AuthError> {
        let mut attempts = 0;
        loop {
            match self.exchange_code(code, redirect_uri) {
                Ok(token) => return Ok(token),
                Err(_) if attempts < self.config.max_retries => {
                    attempts += 1;
                    std::thread::sleep(Duration::from_millis(100 * 2u64.pow(attempts)));
                }
                Err(_) => return Err(AuthError::RetryExhausted),
            }
        }
    }

    fn exchange_code(&self, _code: &str, _redirect_uri: &str) -> Result<String, AuthError> {
        // Simulated token exchange
        Ok("access_token_placeholder".to_string())
    }
}

fn urlencoding_encode(input: &str) -> String {
    input
        .chars()
        .map(|c| match c {
            'A'..='Z' | 'a'..='z' | '0'..='9' | '-' | '_' | '.' | '~' => c.to_string(),
            _ => format!("%{:02X}", c as u32),
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn test_config() -> OAuthConfig {
        OAuthConfig {
            client_id: "test_client".to_string(),
            client_secret: "test_secret".to_string(),
            allowed_redirect_uris: vec!["https://app.example.com/callback".to_string()],
            token_endpoint: "https://provider.example.com/token".to_string(),
            max_retries: 3,
        }
    }

    #[test]
    fn test_valid_redirect() {
        let svc = AuthService::new(test_config());
        let result = svc.initiate_auth("127.0.0.1", "https://app.example.com/callback", "abc123");
        assert!(result.is_ok());
    }

    #[test]
    fn test_invalid_redirect() {
        let svc = AuthService::new(test_config());
        let result = svc.initiate_auth("127.0.0.1", "https://evil.com/callback", "abc123");
        assert_eq!(result.unwrap_err(), AuthError::InvalidRedirectUri);
    }
}
